script:
const stage = element;
    const toggle = stage.querySelector('[data-aurora="toggle"]');
    const label = stage.querySelector('[data-aurora="toggle-label"]');
    const iconPause = stage.querySelector('[data-aurora="icon-pause"]');
    const iconPlay = stage.querySelector('[data-aurora="icon-play"]');

    const read = (name, fallback) => {
      const value = getComputedStyle(stage).getPropertyValue(name).trim();
      return value || fallback;
    };
    const ms = (name, fallback) => parseFloat(read(name, fallback)) || parseFloat(fallback);
    const ease = read('--aurora-ease-breathe', 'cubic-bezier(0.37, 0, 0.63, 1)');

    const spin = (key, duration, direction) => {
      const node = stage.querySelector('[data-aurora="' + key + '"]');
      if (!node) return null;
      const from = direction > 0 ? 'rotate(0deg)' : 'rotate(360deg)';
      const to = direction > 0 ? 'rotate(360deg)' : 'rotate(0deg)';
      return node.animate(
        [{ transform: from }, { transform: to }],
        { duration: duration, iterations: Infinity, easing: 'linear' }
      );
    };

    const animations = [];
    const main = spin('orbit-main', ms('--aurora-duration-orbit', '14000ms'), 1);
    const inner = spin('orbit-inner', ms('--aurora-duration-orbit-inner', '9000ms'), -1);
    const outer = spin('orbit-outer', ms('--aurora-duration-orbit-outer', '22000ms'), 1);
    [main, inner, outer].forEach((a) => { if (a) animations.push(a); });

    const halo = stage.querySelector('[data-aurora="halo"]');
    if (halo) {
      animations.push(halo.animate(
        [
          { transform: 'scale(0.94)', opacity: 0.55 },
          { transform: 'scale(1.06)', opacity: 1 },
          { transform: 'scale(0.94)', opacity: 0.55 }
        ],
        { duration: ms('--aurora-duration-breathe', '4200ms'), iterations: Infinity, easing: ease }
      ));
    }

    const twinkle = ms('--aurora-duration-twinkle', '2600ms');
    stage.querySelectorAll('[data-aurora="mote"]').forEach((mote, index) => {
      animations.push(mote.animate(
        [{ opacity: 0.15 }, { opacity: 0.9 }, { opacity: 0.15 }],
        {
          duration: twinkle + index * 320,
          delay: -index * 410,
          iterations: Infinity,
          easing: ease
        }
      ));
    });

    const calm = window.matchMedia('(prefers-reduced-motion: reduce)');

    const setPlaying = (playing) => {
      animations.forEach((a) => { playing ? a.play() : a.pause(); });
      toggle.setAttribute('aria-pressed', playing ? 'false' : 'true');
      label.textContent = playing ? 'Pause orbits' : 'Play orbits';
      iconPause.hidden = !playing;
      iconPause.style.display = playing ? 'block' : 'none';
      iconPlay.hidden = playing;
      iconPlay.style.display = playing ? 'none' : 'block';
    };

    const applyCalm = () => {
      if (calm.matches) {
        animations.forEach((a) => { a.currentTime = 0; a.pause(); });
        toggle.disabled = true;
        toggle.setAttribute('aria-pressed', 'true');
        toggle.title = 'Motion is off because this device asks for reduced motion';
        label.textContent = 'Motion off';
        iconPause.hidden = true;
        iconPause.style.display = 'none';
        iconPlay.hidden = false;
        iconPlay.style.display = 'block';
      } else {
        toggle.disabled = false;
        toggle.removeAttribute('title');
        setPlaying(true);
      }
    };

    toggle.addEventListener('click', () => {
      setPlaying(toggle.getAttribute('aria-pressed') === 'true');
    });
    calm.addEventListener('change', applyCalm);
    applyCalm();
